\begin{exercise}
\label{exer:path-homotopy-simply-connected}
\dcref{chA:A.7}
Show that if $M$ is a simply connected topological space and $p, q$ are any two points in $M$, then all paths in $M$ from $p$ to $q$ are path-homotopic.
\end{exercise}

